function a2bAuditRun(at, by, seed){
  var groups = [], bugs = [], fails = 0, total = 0;
  if(typeof ZS_CHECK !== 'undefined') ZS_CHECK.forEach(function(g){ var n = g.subs.reduce(function(s, x){ return s + x.items.length; }, 0), f = a2r('aud' + seed + g.n) < .28 ? 1 + Math.floor(a2r('audf' + seed + g.n) * 2) : 0; total += n; fails += f; groups.push({n:g.n, name:g.name, total:n, fail:f}); if(f){ var it = g.subs[0].items[Math.floor(a2r('audi' + seed + g.n) * g.subs[0].items.length)]; bugs.push({id:it[0] + '-' + seed, item:it[0], t:String(it[1]).replace(/\*\(.*$/, '').trim().slice(0, 140), grp:g.name, fix:a2r('audx' + seed + g.n) < .6 ? 'Proposed fix ready (needs your approval)' : 'Needs a person', st:'open'}); } });
  return {id:'AR-' + String(at).slice(-5), at:at, by:by, total:total, fail:fails, groups:groups, bugs:bugs};
}
/* shared helpers */
function a2bCard(title, sub, body, right, cls){ return '<section class="a2-card' + (cls ? ' ' + cls : '') + '"><div class="a2-ch"><div><h2 class="a2-h3">' + title + '</h2>' + (sub ? '<div class="a2-cs">' + sub + '</div>' : '') + '</div>' + (right || '') + '</div>' + body + '</section>'; }
function a2bT(cols, rows, empty){
  if(!rows.length) return '<div class="a2-sm a2-mute" style="padding:6px 0">' + (empty || Le('Nothing in this period', 'এই সময়ে কিছু নেই')) + '</div>';
  return '<div class="a2-tblw a2b-tw"><table class="a2-tbl"><thead><tr>' + cols.map(function(c){ return '<th class="' + (c.cls || '') + '">' + Le(c.en, c.bn) + '</th>'; }).join('') + '</tr></thead><tbody>' +
    rows.map(function(r){ return '<tr>' + cols.map(function(c){ return '<td class="' + (c.cls || '') + (c.k === 'h' ? ' a2-tdh' : c.k === 'w' ? ' a2-tdw' : c.k === 'x' ? ' a2-tdx' : '') + '"' + (c.k !== 'h' ? ' data-l="' + esc(L(c.en, c.bn)) + '"' : '') + '>' + c.r(r) + '</td>'; }).join('') + '</tr>'; }).join('') + '</tbody></table></div>';
}
function a2bSub(items, active){ return '<nav class="a2-views a2b-sub" aria-label="' + Le('Pages in this tab', 'এই ট্যাবের পাতা') + '">' + items.filter(function(x){ return !x[3] || a2Can(x[3]); }).map(function(x){ return '<a class="a2-view' + (x[0] === active ? ' on' : '') + '" href="#' + x[0] + '"' + (x[0] === active ? ' aria-current="page"' : '') + '>' + Le(x[1], x[2]) + '</a>'; }).join('') + '</nav>'; }
function a2bMark(m){ var t = {plan:['Plan', 'পরিকল্পনায়', 'In the build plan, not needed for go-live', 'বানানোর পরিকল্পনায় আছে, চালুর জন্য জরুরি না'], later:['Later', 'পরে', 'Waits for the owner (more stores, S17)', 'মালিকের সিদ্ধান্তের অপেক্ষায়'], parked:['Parked', 'রাখা আছে', 'Hidden slot (S26)', 'লুকানো জায়গা']}[m]; return t ? '<span class="a2-pill line" title="' + esc(L(t[2], t[3])) + '">' + Le(t[0], t[1]) + '</span>' : ''; }
function a2bRange(key, opts){ var r = ui(key || 'a2br', {d:'30'}); opts = opts || [['7', '7 days', '7 দিন'], ['30', '30 days', '30 দিন'], ['90', '90 days', '90 দিন']]; return '<div class="a2-seg" role="group" aria-label="' + Le('Period', 'সময়') + '">' + opts.map(function(x){ return '<button type="button" class="' + (r.d === x[0] ? 'on' : '') + '" data-act="a2b-range" data-k="' + (key || 'a2br') + '" data-v="' + x[0] + '" aria-pressed="' + (r.d === x[0]) + '">' + Le(x[1], x[2]) + '</button>'; }).join('') + '</div>'; }
ACT['a2b-range'] = function(el){ ui(el.getAttribute('data-k'), {}).d = el.getAttribute('data-v'); rerender(); };
function a2bDays(key){ return +ui(key || 'a2br', {d:'30'}).d || 30; }
function a2bFresh(extra){ return '<div class="a2-fresh">' + a2i('clock', 14) + '<span>' + Le('Data up to ', 'তথ্য ') + a2hm(Date.now() - 6 * 60000) + Le('', ' পর্যন্ত') + ' · ' + Le('Sales count delivered orders only, on the courier’s delivered day', 'বিক্রি মানে শুধু ডেলিভারি হওয়া অর্ডার, কুরিয়ারের ডেলিভারির দিনে') + (extra ? ' · ' + extra : '') + '</span></div>'; }
function a2bExportBtn(name){ return a2Can('reports.export') ? '<button type="button" class="a2-btn" data-act="a2b-export" data-n="' + esc(name) + '">' + a2i('dl', 15) + Le('Export', 'নামান') + '</button>' : ''; }
ACT['a2b-export'] = function(el){ var n = el.getAttribute('data-n'); a2Log('Export started: ' + n); toast(L('Export started — you get a notification when the file is ready', 'ফাইল তৈরি হচ্ছে — তৈরি হলে নোটিফিকেশন পাবেন')); setTimeout(function(){ a2S().ntf.unshift({id:'n' + Date.now(), lvl:'fyi', t:'Export ready: ' + n, bn:'ফাইল তৈরি: ' + n, s:'CSV · kept 7 days · download logged', at:Date.now(), href:CUR.path || '/admin/reports'}); saveState(); if(CUR && CUR.page === 'adm2') rerender(); }, 1600); };
function a2bJob(label, ms, fn){ toast(L(label + ' — running…', label + ' — চলছে…')); setTimeout(function(){ try{ fn(); }catch(e){ console.error(e); } saveState(); if(CUR && CUR.page === 'adm2') rerender(); }, ms || 1400); }
function a2bLv(l){ return {urgent:['Urgent', 'জরুরি', 'bad'], important:['Important', 'দরকারি', 'warn'], cw:['Can wait', 'পরে হলেও চলবে', 'info'], glitch:['Short glitch', 'ছোট ঝামেলা', 'line'], fyi:['FYI', 'জানার জন্য', 'line']}[l] || ['—', '—', 'line']; }
function a2bLvPill(l){ var x = a2bLv(l); return '<span class="a2-pill ' + x[2] + '">' + Le(x[0], x[1]) + '</span>'; }
/* the area of an order: district = last part of the address; inside Dhaka, the area before "Dhaka" */
function a2bDistrict(o){ var p = String(o.address || '').split(',').map(function(x){ return x.trim(); }).filter(Boolean), last = p[p.length - 1] || ''; if(/old dhaka/i.test(last)) last = 'Dhaka'; if(/savar|ashulia/i.test(last)) last = 'Dhaka'; return last || L('Unknown', 'অজানা'); }
function a2bArea(o){ var p = String(o.address || '').split(',').map(function(x){ return x.trim(); }).filter(Boolean); if(a2bDistrict(o) !== 'Dhaka') return ''; var i = p.length - 2; while(i > 0 && /^(road|house|flat|block|sector|lane)\b/i.test(p[i])) i--; return (p[i] || '').replace(/ R\/A$/, ''); }
/* delivered rows for a period, by the SAME rule as a2M (delivered or partly delivered on the delivered day; kept share) */
function a2bRows(m){
  var key = 'rows' + m.days + '/' + m.start; if(A2.mc[key]) return A2.mc[key];
  var out = []; a2Orders().forEach(function(o){ var a = a2O(o); if((a.ost === 'DELIVERED' || a.ost === 'PARTIALLY_DELIVERED') && o.deliveredAt >= m.start && o.deliveredAt < m.end){ out.push({o:o, a:a, v:Math.round(a2Goods(o) * (a.ost === 'PARTIALLY_DELIVERED' ? (a.keptShare || .5) : 1))}); } });
  return (A2.mc[key] = out);
}
function a2bCheckSum(rows, m){ var s = rows.reduce(function(t, r){ return t + r.v; }, 0); return '<div class="a2-xs a2b-il ' + (s === m.sales ? 'a2-mute' : 'a2b-badtxt') + '" style="margin-top:10px;display:flex">' + a2i(s === m.sales ? 'check' : 'alert', 13) + (s === m.sales ? Le('Adds up to delivered sales ', 'মোট মেলে ডেলিভারি হওয়া বিক্রির সাথে ') + a2tk(m.sales) : Le('Does not add up — please report', 'মিলছে না — জানান')) + '</div>'; }
function a2bGroup(rows, keyFn){ var g = {}; rows.forEach(function(r){ var k = keyFn(r); if(k == null) return; var x = g[k] = g[k] || {k:k, n:0, v:0}; x.n++; x.v += r.v; }); return Object.keys(g).map(function(k){ return g[k]; }).sort(function(a, b){ return b.v - a.v; }); }
function a2bPayName(m){ return ({cod:L('Cash on delivery', 'ক্যাশ অন ডেলিভারি'), bkash:'bKash', nagad:'Nagad', card:L('Card', 'কার্ড'), bank:L('Bank', 'ব্যাংক'), online:L('Online', 'অনলাইন')})[m] || m || 'COD'; }
function a2bSrcName(s){ s = s || 'website'; if(s.indexOf('landing:') === 0) return L('Landing page · ', 'ল্যান্ডিং পেজ · ') + s.slice(8); return ({website:L('Website', 'ওয়েবসাইট'), chat:L('Chat', 'চ্যাট'), phone:L('Phone order', 'ফোনে অর্ডার'), 'walk-in':L('Walk-in', 'দোকানে এসে')})[s] || s; }

