function a2bRepeat(m){ var ph = {}, all = {}; a2Orders().forEach(function(o){ var k = String(o.phone || '').replace(/\D/g, ''); if(!k) return; all[k] = all[k] || []; all[k].push(o.createdAt); if(o.createdAt >= m.start && o.createdAt < m.end) ph[k] = 1; }); var n = 0, rep = 0; Object.keys(ph).forEach(function(k){ n++; if(all[k].length > 1) rep++; }); return {n:n, rep:rep, rate:n ? rep / n : null}; }
function a2bConv(m){ var T = window.EXTRACK, ev = []; try{ ev = T && T.all ? T.all() : []; }catch(e){} var s = {}; ev.forEach(function(e){ if(e && e.t >= m.start && e.t < m.end && e.sid) s[e.sid] = 1; }); var n = Object.keys(s).length; return {n:n, rate:n >= 20 ? Math.min(1, m.ordersN / n) : null}; }
function a2bComment(m, pv){
  var out = [], t = a2Trend(m.sales, pv.sales);
  out.push(t == null ? Le('Not enough earlier data to compare yet.', 'তুলনার জন্য আগের তথ্য এখনো কম।') : Le('Delivered sales ' + (t >= 0 ? 'rose ' : 'fell ') + Math.abs(t * 100).toFixed(1) + '% against the previous period.', 'আগের সময়ের চেয়ে বিক্রি ' + Math.abs(t * 100).toFixed(1) + '% ' + (t >= 0 ? 'বেড়েছে' : 'কমেছে') + '।'));
  var bc = Object.keys(m.byCour).map(function(k){ return {k:k, r:m.byCour[k].rate, n:m.byCour[k].den}; }).filter(function(x){ return x.n >= 2 && x.r != null; }).sort(function(a, b){ return a.r - b.r; });
  if(bc.length) out.push(Le('Lowest delivery success: ' + a2CourName(bc[0].k) + ' at ' + a2pct(bc[0].r, 0) + ' (' + bc[0].n + ' parcels).', 'সবচেয়ে কম সফলতা: ' + a2CourName(bc[0].k) + ' — ' + a2pct(bc[0].r, 0) + '।'));
  if(m.coverage < 1) out.push(Le('ERP cost is missing for some sold lines (' + a2pct(1 - m.coverage, 0) + '); profit leaves them out instead of counting 0.', 'কিছু লাইনের ERP খরচ নেই (' + a2pct(1 - m.coverage, 0) + '); লাভের হিসাবে সেগুলো বাদ, 0 ধরা হয়নি।'));
  if(m.adMissing) out.push(Le(m.adMissing + ' days of ad spend are not imported yet — shown as missing.', m.adMissing + ' দিনের বিজ্ঞাপন খরচ আসেনি — খালি দেখানো হচ্ছে।'));
  if(m.unsettled) out.push(Le(m.unsettled + ' delivered COD parcels are not settled by the courier yet, so sales stay provisional.', m.unsettled + 'টা COD পার্সেলের টাকা কুরিয়ার এখনো দেয়নি, তাই বিক্রি অস্থায়ী।'));
  return out;
}

