function a2bZ(a, b2){ var p1 = a[1] / a[0], p2 = b2[1] / b2[0], p = (a[1] + b2[1]) / (a[0] + b2[0]), se = Math.sqrt(p * (1 - p) * (1 / a[0] + 1 / b2[0])); var z = se ? (p2 - p1) / se : 0; var t = 1 / (1 + .2316419 * Math.abs(z)), dd = .3989423 * Math.exp(-z * z / 2), pr = dd * t * (.3193815 + t * (-.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274)))); return {lift:p1 ? (p2 - p1) / p1 : 0, conf:1 - 2 * pr, p1:p1, p2:p2}; }
