/* framework hook (2B): a row checkbox sits inside a clickable row (tr[data-act]); the shop's global click handler calls
   preventDefault() for that row, which cancels the checkbox toggle, so bulk selection never worked with a real tap or click.
   Stopping only that click in the capture phase keeps the toggle and its change event; the row's own click is not needed. */
document.addEventListener('click', function(ev){ var t = ev.target; if(t && t.matches && t.matches('input[type="checkbox"][data-change]') && t.closest('[data-act]')) ev.stopPropagation(); }, true);
